// The development variant of ./jsx-runtime.js.
const runtime = require('react/jsx-dev-runtime')

function mark(type, props) {
  return typeof type === 'string' ? { ...props, 'data-custom-jsx': '' } : props
}

exports.Fragment = runtime.Fragment
exports.jsxDEV = (type, props, key, isStaticChildren, source, self) =>
  runtime.jsxDEV(type, mark(type, props), key, isStaticChildren, source, self)
